/**
 * КОДЫ СТРАН ИЗ MRZ: три буквы документа -> две буквы, какие понимает Intl.DisplayNames.
 *
 * Одной строкой по пять знаков на страну: 249 стран весят меньше килобайта, а объект из
 * 249 ключей в разборе кода занял бы вчетверо больше и читался бы дольше при сборке.
 * Сделано скриптом из списка ISO 3166-1 (datasets/country-codes), править руками нечего --
 * кроме особых кодов ниже, которых в ISO нет вовсе.
 */
const ТАБЛИЦА = '';

/**
 * Особые коды, какие бывают только в документах. ИКАО разрешает их наравне со странами, и
 * человек, увидевший «D» в паспорте, должен получить «Германия», а не пустоту.
 */
export const ОСОБЫЕ = {
  D: 'DE', GBD: 'GB', GBN: 'GB', GBO: 'GB', GBP: 'GB', GBS: 'GB',
  EUE: 'EU', RKS: 'XK', UNO: 'UN', UNA: 'UN', UNK: 'UN',
};

/** Коды без страны вовсе: так помечают документы беженцев и людей без гражданства. */
export const БЕЗ_СТРАНЫ = ['XXA', 'XXB', 'XXC', 'XXX', 'XOM', 'XCC', 'XCO', 'XEC', 'XPO', 'XDC', 'XIM'];

/** Две буквы по трём. Неизвестный код -- пусто: выдумывать страну нельзя. */
export function двеБуквы(код) {
  if (typeof код !== 'string') return '';
  const к = код.toUpperCase();
  if (ОСОБЫЕ[к]) return ОСОБЫЕ[к];
  if (к.length !== 3) return '';
  const и = ТАБЛИЦА.indexOf(к);
  return и >= 0 && и % 5 === 0 ? ТАБЛИЦА.slice(и + 3, и + 5) : '';
}
